SOURCES = {
 'DAG': ('DAgger', 'dagger', 'AISTATS 2011, Original-Proceedings', 'https://proceedings.mlr.press/v15/ross11a/ross11a.pdf'),
 'DART': ('DART', 'dart', 'CoRL 2017, Original-Proceedings', 'https://proceedings.mlr.press/v78/laskey17a/laskey17a.pdf'),
 'SBC': ('Stable-BC', 'stable_bc', 'Preprint arXiv:2408.06246v1, 2024; Journalinhalt nicht abgeglichen', 'https://arxiv.org/pdf/2408.06246v1'),
 'ACT': ('ACT', 'act', 'RSS 2023, Original-Proceedings', 'https://www.roboticsproceedings.org/rss19/p016.pdf'),
 'DP': ('Diffusion Policy', 'diffusion_policy', 'RSS 2023, Original-Proceedings', 'https://www.roboticsproceedings.org/rss19/p026.pdf'),
}

def generate():
 root = Path(__file__).resolve().parents[1]
 topics = ['Behavioural Cloning','Covariate Shift','Error Accumulation','Robustness','Interactive Imitation Learning','Action Chunking','Generative Policies','Evaluation']
 lines = ['# Thematisches Claim-Register', '',
  'Alle Aussagen und Paraphrasen in den Einträgen sind **A: Quellenaussagen**. Kapitelpositionen sind **B: redaktionelle Verwendungsvorschläge**. **C: Projektbefunde** stehen getrennt in [relation_to_our_results.md](comparisons/relation_to_our_results.md). Klassen und Seitenkonvention: [INDEX.md](INDEX.md).', '',
  'Primärquelle bedeutet hier die Originalautoren; bei `P-` stammt die geprüfte Evidenz ausschließlich aus einem Preprint. Keine Journal-Garantie aus diesen Stellen ableiten. Zahlen sind Autorenangaben, keine neu berechneten Projektergebnisse.', '']
 for topic in topics:
  lines += ['## '+topic,'']
  for id,theme,page,section,cls,claim,para,use,quote in CLAIMS:
   if theme != topic: continue
   key=id.split('-')[0]; name,slug,version,url=SOURCES[key]
   lines += [f'<a id="{id.lower()}"></a>', f'### {id}', '',
    f'- **ID:** `{id}`', f'- **Aussage (A):** {claim}',
    f'- **Primärquelle:** {name}, {version}; [Original-PDF]({url}#page={page}) / [eingefrorenes PDF](_research/{slug}.pdf#page={page})',
    f'- **Seite:** PDF S. {page}; **Abschnitt:** {section}', f'- **Evidenzklasse:** {cls}',
    f'- **Paraphrase (A):** {para}', f'- **Mögliche Kapitelposition (B):** {use}.', '']
 (root/'CLAIMS.md').write_text('\n'.join(lines),encoding='utf-8')
 for key,(name,slug,version,url) in SOURCES.items():
  path=root/'methods'/f'{slug}.md'
  if not path.exists(): continue
  body=path.read_text(encoding='utf-8').split('## Belegstellen mit Claim-IDs')[0].rstrip()
  extra=['','## Belegstellen mit Claim-IDs','',
   f'Zehn relevante Stellen aus **{version}**. Jede Seite ist eine konkrete PDF-Seite der archivierten Fassung. Originalzitate sind bewusst auf einen kurzen Auszug pro Paper begrenzt; „—“ bedeutet, dass hier kein Originalzitat gespeichert wird. Paraphrasen sind A; Verwendungen sind B. Der Projektbezug C steht in Abschnitt 13–14.','']
  for id,theme,page,section,cls,claim,para,use,quote in CLAIMS:
   if id.split('-')[0]!=key: continue
   extra += [f'### {id} — PDF S. {page}', '',
    f'- **Abschnitt:** {section}. [Fundstelle]({url}#page={page})',
    f'- **Kurzes Originalzitat:** '+(f'“{quote}”' if quote else '—'),
    f'- **Genaue Paraphrase (A):** {para}',
    f'- **Mögliche Verwendung (B):** {use}.',
    f'- **Claim-ID:** [{id}](../CLAIMS.md#{id.lower()}); Evidenzklasse {cls}.','']
  path.write_text(body+'\n'+'\n'.join(extra),encoding='utf-8')

if __name__ == '__main__': generate()
